ALTER TABLE subscriptions ADD COLUMN provider_event_created bigint NOT NULL DEFAULT 0, ADD COLUMN monthly_amount numeric, ADD COLUMN currency text;
CREATE FUNCTION apply_billing_snapshot(event_id text,event_hash text,workspace uuid,customer text,subscription text,plan_name text,subscription_state text,period_end timestamptz,event_created bigint,amount numeric,currency_code text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE previous record; BEGIN
IF plan_name NOT IN ('free','solo','team','enterprise') OR subscription_state NOT IN ('active','trialing','past_due','unpaid','canceled','cancelled','incomplete','incomplete_expired','paused') OR amount<0 THEN RAISE EXCEPTION 'Invalid billing snapshot'; END IF;
PERFORM set_config('app.workspace_id',workspace::text,true); PERFORM 1 FROM workspaces WHERE id=workspace FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Unknown workspace'; END IF;
SELECT * INTO previous FROM billing_events WHERE id=event_id; IF FOUND THEN IF previous.payload_hash<>event_hash THEN RAISE EXCEPTION 'Billing event changed'; END IF; RETURN false; END IF;
INSERT INTO billing_events(id,payload_hash) VALUES(event_id,event_hash);
SELECT * INTO previous FROM subscriptions WHERE workspace_id=workspace;
IF FOUND AND previous.provider_event_created>event_created THEN RETURN false; END IF;
IF FOUND AND previous.provider_subscription_id IS NOT NULL AND previous.provider_subscription_id<>subscription AND previous.state IN ('active','trialing') THEN RAISE EXCEPTION 'Subscription conflict'; END IF;
INSERT INTO subscriptions(workspace_id,provider_customer_id,provider_subscription_id,plan,state,current_period_end,provider_event_created,monthly_amount,currency) VALUES(workspace,customer,subscription,plan_name,subscription_state,period_end,event_created,amount,currency_code) ON CONFLICT(workspace_id) DO UPDATE SET provider_customer_id=EXCLUDED.provider_customer_id,provider_subscription_id=EXCLUDED.provider_subscription_id,plan=EXCLUDED.plan,state=EXCLUDED.state,current_period_end=EXCLUDED.current_period_end,provider_event_created=EXCLUDED.provider_event_created,monthly_amount=EXCLUDED.monthly_amount,currency=EXCLUDED.currency,updated_at=now();
UPDATE workspaces SET plan=CASE WHEN subscription_state IN ('active','trialing') THEN plan_name ELSE 'free' END WHERE id=workspace; RETURN true; END $$;
REVOKE ALL ON FUNCTION apply_billing_snapshot(text,text,uuid,text,text,text,text,timestamptz,bigint,numeric,text) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION apply_billing_event(text,text,uuid,text,text,text,text,timestamptz) FROM watchtower_app;
GRANT EXECUTE ON FUNCTION apply_billing_snapshot(text,text,uuid,text,text,text,text,timestamptz,bigint,numeric,text) TO watchtower_app;
CREATE FUNCTION workspace_capabilities(actor text,tenant uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE access record; BEGIN SELECT * INTO access FROM authorize_workspace(actor,tenant); IF (access IS NULL AND NOT EXISTS(SELECT 1 FROM support_sessions s JOIN auth_user u ON u.id=s.actor_id WHERE s.actor_id=actor AND s.workspace_id=tenant AND s.expires_at>now() AND u."platformAdmin")) OR access.suspended THEN RAISE EXCEPTION 'Workspace denied' USING ERRCODE='42501'; END IF; RETURN jsonb_build_object('regions',coalesce((SELECT jsonb_agg(jsonb_build_object('id',p.id,'region',p.region,'capabilities',p.capabilities,'lastSeenAt',p.last_seen_at,'private',p.workspace_id IS NOT NULL)) FROM probes p WHERE (p.workspace_id IS NULL OR p.workspace_id=tenant) AND NOT p.draining AND p.last_seen_at>now()-interval '2 minutes'),'[]'::jsonb)); END $$;
REVOKE ALL ON FUNCTION workspace_capabilities(text,uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION workspace_capabilities(text,uuid) TO watchtower_app;
CREATE OR REPLACE FUNCTION platform_snapshot(actor text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE item record; tenants jsonb:='[]'; BEGIN IF NOT EXISTS(SELECT 1 FROM auth_user WHERE id=actor AND "platformAdmin") THEN RAISE EXCEPTION 'Platform access denied' USING ERRCODE='42501'; END IF; FOR item IN SELECT DISTINCT workspace_id FROM workspace_access LOOP PERFORM set_config('app.workspace_id',item.workspace_id::text,true); SELECT tenants||jsonb_build_array(jsonb_build_object('id',w.id,'name',w.name,'plan',w.plan,'suspended',w.suspended,'created_at',w.created_at,'monitors',(SELECT count(*) FROM monitors WHERE workspace_id=w.id AND archived_at IS NULL),'members',(SELECT count(*) FROM memberships WHERE workspace_id=w.id),'subscription',(SELECT jsonb_build_object('state',s.state,'monthlyAmount',s.monthly_amount,'currency',s.currency) FROM subscriptions s WHERE s.workspace_id=w.id))) INTO tenants FROM workspaces w WHERE id=item.workspace_id; END LOOP; RETURN jsonb_build_object('tenants',tenants,'probes',coalesce((SELECT jsonb_agg(to_jsonb(p)-'enrollment_hash') FROM probes p),'[]'::jsonb),'flags',coalesce((SELECT jsonb_agg(to_jsonb(f)) FROM feature_flags f),'[]'::jsonb)); END $$;
